template<Op Code, int Inputs, int Outputs> inline void run_kernel(const std::array<KernelRead,5>& source, const std::array<uint32_t*,2>& target, int lanes) {
    for (int group=0; group<lanes; group+=4) {
        std::array<uint32_t,4> result{};
        for (int lane=0; lane<4; lane++) { std::array<uint32_t,5> values{};
            if constexpr (Inputs>0) values[0]=source[0].at(group+lane);
            if constexpr (Inputs>1) values[1]=source[1].at(group+lane);
            if constexpr (Inputs>2) values[2]=source[2].at(group+lane);
            if constexpr (Inputs>3) values[3]=source[3].at(group+lane);
            if constexpr (Inputs>4) values[4]=source[4].at(group+lane);
            result[lane]=evaluate<Code>(values); }
        for (int lane=0; lane<4; lane++) { target[0][group+lane]=result[lane]; if constexpr (Outputs==2) target[1][group+lane]=result[lane]; }
    }
}
